#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <numeric>
#include <sstream>
#include <string>
#include <vector>

static int bit_count(std::uint64_t value) {
    int count = 0;
    while (value != 0) {
        count += static_cast<int>(value & 1U);
        value >>= 1U;
    }
    return count;
}

static int f(std::uint64_t mask, int input) {
    return static_cast<int>((mask >> input) & 1U);
}

int main() {
    std::cout << "row_index,essential_variable_count,algebraic_degree,anf_term_count,"
                 "fourier_degree,walsh_max_abs,walsh_zero_count,nonlinearity,"
                 "hamming_boundary_edges,sensitivity_min,sensitivity_max,sensitivity_sum,"
                 "monotone_violation_count,is_constant,is_balanced,is_monotone,is_antitone,"
                 "is_symmetric,is_self_dual,is_affine_function,is_bent,"
                 "is_correlation_immune_order_1,is_projection,is_negated_projection\n";
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        std::stringstream stream(line);
        std::string token;
        std::getline(stream, token, ',');
        const int row = std::stoi(token);
        std::getline(stream, token, ',');
        const int arity = std::stoi(token);
        std::getline(stream, token, ',');
        const std::uint64_t mask = std::stoull(token);
        const int size = 1 << arity;

        std::vector<int> anf(size);
        for (int x = 0; x < size; ++x) anf[x] = f(mask, x);
        for (int bit = 0; bit < arity; ++bit) {
            for (int x = 0; x < size; ++x) {
                if ((x & (1 << bit)) != 0) anf[x] ^= anf[x ^ (1 << bit)];
            }
        }
        int algebraic_degree = 0;
        int anf_terms = 0;
        for (int x = 0; x < size; ++x) {
            if (anf[x] != 0) {
                ++anf_terms;
                algebraic_degree = std::max(algebraic_degree, bit_count(x));
            }
        }

        std::vector<int> walsh(size);
        for (int x = 0; x < size; ++x) walsh[x] = f(mask, x) == 0 ? 1 : -1;
        for (int step = 1; step < size; step *= 2) {
            for (int start = 0; start < size; start += 2 * step) {
                for (int offset = 0; offset < step; ++offset) {
                    const int left = walsh[start + offset];
                    const int right = walsh[start + offset + step];
                    walsh[start + offset] = left + right;
                    walsh[start + offset + step] = left - right;
                }
            }
        }
        int fourier_degree = 0;
        int walsh_max = 0;
        int walsh_zeros = 0;
        for (int index = 0; index < size; ++index) {
            if (walsh[index] != 0) fourier_degree = std::max(fourier_degree, bit_count(index));
            walsh_max = std::max(walsh_max, std::abs(walsh[index]));
            walsh_zeros += walsh[index] == 0;
        }

        std::vector<int> sensitivity(size, 0);
        std::vector<bool> essential(arity, false);
        int boundary_twice = 0;
        for (int x = 0; x < size; ++x) {
            for (int bit = 0; bit < arity; ++bit) {
                if (f(mask, x) != f(mask, x ^ (1 << bit))) {
                    ++sensitivity[x];
                    ++boundary_twice;
                    essential[bit] = true;
                }
            }
        }
        const int sensitivity_sum = std::accumulate(sensitivity.begin(), sensitivity.end(), 0);
        const int sensitivity_min = *std::min_element(sensitivity.begin(), sensitivity.end());
        const int sensitivity_max = *std::max_element(sensitivity.begin(), sensitivity.end());

        bool monotone = true;
        bool antitone = true;
        int monotone_violations = 0;
        for (int bit = 0; bit < arity; ++bit) {
            for (int x = 0; x < size; ++x) {
                if ((x & (1 << bit)) != 0) continue;
                const int lower = f(mask, x);
                const int upper = f(mask, x | (1 << bit));
                if (lower > upper) { monotone = false; ++monotone_violations; }
                if (lower < upper) antitone = false;
            }
        }
        bool symmetric = true;
        for (int weight = 0; weight <= arity; ++weight) {
            int observed = -1;
            for (int x = 0; x < size; ++x) {
                if (bit_count(x) != weight) continue;
                if (observed < 0) observed = f(mask, x);
                if (observed != f(mask, x)) symmetric = false;
            }
        }
        bool self_dual = true;
        for (int x = 0; x < size; ++x) {
            if (f(mask, x) != 1 - f(mask, (size - 1) ^ x)) self_dual = false;
        }
        bool projection = false;
        bool negated_projection = false;
        for (int bit = 0; bit < arity; ++bit) {
            bool direct = true;
            bool negated = true;
            for (int x = 0; x < size; ++x) {
                direct = direct && f(mask, x) == ((x >> bit) & 1);
                negated = negated && f(mask, x) == 1 - ((x >> bit) & 1);
            }
            projection = projection || direct;
            negated_projection = negated_projection || negated;
        }
        int satisfying = 0;
        for (int x = 0; x < size; ++x) satisfying += f(mask, x);
        const bool bent = arity % 2 == 0 && std::all_of(
            walsh.begin(), walsh.end(), [arity](int coefficient) {
                return std::abs(coefficient) == (1 << (arity / 2));
            }
        );
        bool correlation_immune = true;
        for (int bit = 0; bit < arity; ++bit) correlation_immune = correlation_immune && walsh[1 << bit] == 0;

        std::cout << row << ',' << std::count(essential.begin(), essential.end(), true) << ','
                  << algebraic_degree << ',' << anf_terms << ',' << fourier_degree << ','
                  << walsh_max << ',' << walsh_zeros << ',' << (size / 2 - walsh_max / 2) << ','
                  << boundary_twice / 2 << ',' << sensitivity_min << ',' << sensitivity_max << ','
                  << sensitivity_sum << ',' << monotone_violations << ','
                  << (satisfying == 0 || satisfying == size) << ',' << (2 * satisfying == size) << ','
                  << monotone << ',' << antitone << ',' << symmetric << ',' << self_dual << ','
                  << (algebraic_degree <= 1) << ',' << bent << ',' << correlation_immune << ','
                  << projection << ',' << negated_projection << '\n';
    }
}

